{
  "entry": "main.js",
  "name": "STARBOX COFFEE",
  "description": "CLIMB. COLLECT. BREW. Version 2.2: a progressive Espresso climb and advanced Latte switchbacks. Circle the glass mug with Milo or Mira, master slippery ceramic and regenerating biscuits, collect your recipe and outrun rising coffee. Permanent timber detours and Perfect Coffee cards. Free arcade play.",
  "maxPlayers": 8,
  "credits": [
    {
      "work": "STARBOX V2 baristas and glass-mug cafe cover",
      "by": "Original artwork created with OpenAI image generation for STARBOX COFFEE"
    },
    {
      "work": "Milo explorer animation polish",
      "by": "Original OpenAI-generated sprite art from the supplied character direction; source and frame data preserved"
    },
    {
      "work": "Original cafe architecture, surface textures, gameplay and synthesized sound",
      "by": "Created for STARBOX COFFEE"
    },
    {
      "work": "DejaVu Sans, Serif and Mono rasterised UI lettering",
      "by": "DejaVu font team; Bitstream Vera licence in assets/font-license.txt"
    }
  ],
  "loading": {
    "background": "#1e3932",
    "accent": "#c8a66a",
    "text": "#f2f0e8",
    "cover": "assets/v2/cover-v2.jpg",
    "fit": "cover"
  },
  "ui": "minimized",
  "stick": false
}

import * as THREE from 'three';

/** Crisp pixel sprites share the world's sampled depth, rather than sitting over it. */
export function createBarista(assets, depthTexture) {
  const entries = {};
  for (const id of ['boy', 'girl']) {
    const source = id === 'boy' && assets.primary ? assets.primary : assets;
    const size = source.meta.gameplayAtlasSize || 320;
    const canvas = new OffscreenCanvas(size, size), ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false; ctx.drawImage(source.bitmap, 0, 0, size, size);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.minFilter = texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;
    entries[id] = {texture, meta:source.meta, character:source.meta.characters[id]};
  }
  const uniforms = {
    atlas:{value:entries.boy.texture}, sceneDepth:{value:depthTexture},
    viewSize:{value:new THREE.Vector2(640,360)}, frameRect:{value:new THREE.Vector4()},
    anchor:{value:new THREE.Vector2(.5,0)}, flip:{value:1},
    texel:{value:new THREE.Vector2(1/320,1/320)}, warmth:{value:0}, bounce:{value:0}
  };
  const material = new THREE.ShaderMaterial({
    uniforms, transparent:true, depthWrite:false, depthTest:false,
    vertexShader:`
      uniform vec4 frameRect;
      uniform vec2 anchor;
      uniform float flip;
      varying vec2 spriteUV;
      varying vec2 localUV;
      void main() {
        localUV=uv;
        spriteUV=frameRect.xy+vec2(flip>0.0?uv.x:1.0-uv.x,uv.y)*frameRect.zw;
        vec3 p=position;
        p.xy+=vec2(0.5)-anchor;
        gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);
      }`,
    fragmentShader:`
      uniform sampler2D atlas;
      uniform sampler2D sceneDepth;
      uniform vec2 viewSize;
      uniform vec2 texel;
      uniform float warmth;
      uniform float bounce;
      varying vec2 spriteUV;
      varying vec2 localUV;
      void main() {
        float worldDepth=texture2D(sceneDepth,gl_FragCoord.xy/viewSize).r;
        if(gl_FragCoord.z>worldDepth+0.000015) discard;
        vec4 pixel=texture2D(atlas,spriteUV);
        if(pixel.a<0.16) discard;
        float edge=1.0-min(texture2D(atlas,spriteUV+vec2(texel.x,0.0)).a,
                           texture2D(atlas,spriteUV+vec2(0.0,texel.y)).a);
        vec3 color=pixel.rgb*vec3(0.96,0.975,0.91);
        color+=vec3(0.13,0.085,0.025)*edge*(0.25+warmth);
        color+=vec3(0.045,0.025,0.008)*(1.0-localUV.y)*bounce;
        color*=1.0+warmth*0.07;
        gl_FragColor=vec4(color,pixel.a);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  const hero=new THREE.Mesh(new THREE.PlaneGeometry(1,1),material);
  hero.name='Depth-tested pixel barista';hero.frustumCulled=false;
  const scene=new THREE.Scene(),root=new THREE.Group();
  root.scale.setScalar(.24);root.position.y=.85;root.add(hero);scene.add(root);
  let runCycle=0;
  function update(sample, options) {
    const {character='boy',time=0,dt=0,camera,facing=1,landLeft=0,width=640,height=360,light=0}=options;
    const entry=entries[character],meta=entry.meta;
    const animations=entry.character.animations||meta.animations;
    const speed=Math.abs(sample.vTheta);
    let action=sample.result?.success?'victory':landLeft>0&&sample.grounded?'land':
      !sample.grounded?(sample.vY>1.5?'jump':sample.vY>-.8&&animations.apex?'apex':'fall'):
      speed>.12?'run':'idle';
    const animation=animations[action];
    if(action==='run')runCycle+=dt*(animation.fps||10)*Math.max(.55,speed/1.2);
    const clock=action==='run'?runCycle:action==='land'?Math.max(0,.18-landLeft)*(animation.fps||10):time*(animation.fps||1);
    const frame=entry.character.frames[animation.frames[Math.floor(clock)%animation.frames.length]];
    const [x,y,w,h]=frame.rect,[iw,ih]=meta.imageSize;
    uniforms.atlas.value=entry.texture;
    uniforms.frameRect.value.set(x/iw,1-(y+h)/ih,w/iw,h/ih);
    uniforms.anchor.value.set(facing<0?1-frame.anchor[0]:frame.anchor[0],1-frame.anchor[1]);
    uniforms.flip.value=facing;
    uniforms.texel.value.set(1/entry.texture.image.width,1/entry.texture.image.height);
    uniforms.viewSize.value.set(width,height);
    uniforms.warmth.value=light;
    uniforms.bounce.value=Math.max(0,1-(sample.y-sample.coffeeY)/5);
    const size=1.62/meta.nominalBodyHeight;
    hero.position.set(Math.sin(sample.theta)*5,sample.y,Math.cos(sample.theta)*5);
    hero.scale.set(w*size,h*size,1);
    hero.quaternion.copy(camera.quaternion);
  }
  return {scene,root,hero,update,dispose(){
    hero.geometry.dispose();material.dispose();
    for(const entry of Object.values(entries))entry.texture.dispose();
  }};
}

export function createContactShadow(world) {
  const canvas=new OffscreenCanvas(64,64),ctx=canvas.getContext('2d');
  const gradient=ctx.createRadialGradient(32,32,2,32,32,31);
  gradient.addColorStop(0,'rgba(35,22,12,0.7)');
  gradient.addColorStop(.4,'rgba(35,22,12,0.36)');gradient.addColorStop(1,'rgba(35,22,12,0)');
  ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);
  const texture=new THREE.CanvasTexture(canvas);texture.generateMipmaps=false;
  const material=new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false,
    polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});
  const shadow=new THREE.Mesh(new THREE.PlaneGeometry(1,1),material);
  shadow.rotation.x=-Math.PI/2;shadow.renderOrder=2;world.add(shadow);
  return {object:shadow,update(run,visible){
    const floor=run.platforms.filter(p=>!p.collapsed&&p.y<=run.y+.025&&
      Math.abs(Math.atan2(Math.sin(run.theta-p.angle),Math.cos(run.theta-p.angle)))<p.halfWidth+.01)
      .sort((a,b)=>b.y-a.y)[0];
    const gap=floor?run.y-floor.y:10;
    shadow.visible=Boolean(visible&&floor&&gap<3);
    if(!shadow.visible)return;
    shadow.position.set(Math.sin(run.theta)*5,floor.y+.018,Math.cos(run.theta)*5);
    shadow.scale.set(.90+gap*.17,.62+gap*.13,1);
    material.opacity=Math.max(.08,.72-gap*.18);
  },dispose(){world.remove(shadow);shadow.geometry.dispose();material.dispose();texture.dispose();}};
}

import * as THREE from 'three';
import {RADIUS} from './rules.js';

function shade(geometry) {
  const n=geometry.getAttribute('normal'),c=[];
  for(let i=0;i<n.count;i++) {
    const dot=n.getY(i)*.72+n.getZ(i)*.51-n.getX(i)*.3;
    const light=dot>.55?1.12:dot>-.1?.88:.60;
    c.push(light,light,light);
  }
  geometry.setAttribute('color',new THREE.Float32BufferAttribute(c,3));
  return geometry;
}
function starGeometry() {
  const shape=new THREE.Shape();
  for(let i=0;i<10;i++) {
    const a=i*Math.PI/5+Math.PI/2,r=i%2?.16:.35,x=Math.cos(a)*r,y=Math.sin(a)*r;
    if(i)shape.lineTo(x,y);else shape.moveTo(x,y);
  }
  shape.closePath();
  const geometry=new THREE.ExtrudeGeometry(shape,{depth:.1,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:1,steps:1});
  geometry.translate(0,0,-.05);return shade(geometry);
}

export function createCollectibles(world,course,assets={}) {
  const root=new THREE.Group();world.add(root);
  const material=new THREE.MeshBasicMaterial({vertexColors:true});
  const glowCanvas=new OffscreenCanvas(64,64),ctx=glowCanvas.getContext('2d');
  const gradient=ctx.createRadialGradient(32,32,3,32,32,31);
  gradient.addColorStop(0,'rgba(255,255,255,0.65)');gradient.addColorStop(.5,'rgba(255,255,255,0.14)');
  gradient.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);
  const glowTexture=new THREE.CanvasTexture(glowCanvas);glowTexture.generateMipmaps=false;
  const haloMaterial=new THREE.MeshBasicMaterial({map:glowTexture,color:0xf2cc86,transparent:true,opacity:.38,depthWrite:false});
  const shadowMaterial=new THREE.MeshBasicMaterial({map:glowTexture,color:0x20140d,transparent:true,opacity:.48,depthWrite:false});
  const sphere=shade(new THREE.SphereGeometry(1,16,10));
  const profile=[[0,-.33],[.13,-.29],[.22,-.16],[.23,-.02],[.18,.14],[.08,.32],[0,.47]];
  const drop=shade(new THREE.LatheGeometry(profile.map(p=>new THREE.Vector2(...p)),16));
  const crease=new THREE.CatmullRomCurve3([new THREE.Vector3(-.02,-.23,.145),
    new THREE.Vector3(-.065,-.06,.18),new THREE.Vector3(.045,.08,.18),new THREE.Vector3(.025,.23,.13)]);
  const star=starGeometry(),seam=shade(new THREE.TubeGeometry(crease,12,.022,5,false));
  const haloGeometry=new THREE.PlaneGeometry(1.25,1.25);
  const shadowGeometry=new THREE.PlaneGeometry(.72,.53);shadowGeometry.rotateX(-Math.PI/2);
  const types={bean:[],milk:[],star:[]};
  for(const item of course.ingredients)types[item.kind]?.push(item);
  const batches={},all=[];
  for(const [kind,list] of Object.entries(types)) {
    if(!list.length)continue;
    const geo=kind==='bean'?sphere:kind==='milk'?drop:star;
    const batch=new THREE.InstancedMesh(geo,material,list.length);
    batch.frustumCulled=false;root.add(batch);batches[kind]=batch;
    list.forEach((item,index)=>{
      batch.setColorAt(index,new THREE.Color(kind==='bean'?0xaf6637:kind==='milk'?0xfff1d0:0xf7bb54));
      all.push({...item,index,batch,phase:index*1.7});
    });
  }
  const beans=types.bean;
  const seams=beans.length?new THREE.InstancedMesh(seam,material,beans.length):null;
  if(seams) {
    seams.frustumCulled=false;root.add(seams);
    beans.forEach((_,i)=>seams.setColorAt(i,new THREE.Color(0x40281b)));
  }
  const halos=new THREE.InstancedMesh(haloGeometry,haloMaterial,all.length);
  halos.frustumCulled=false;root.add(halos);
  const shadows=new THREE.InstancedMesh(shadowGeometry,shadowMaterial,all.length);
  shadows.frustumCulled=false;root.add(shadows);
  const highlights=new THREE.InstancedMesh(sphere,material,all.length);
  highlights.frustumCulled=false;root.add(highlights);
  all.forEach((item,i)=>highlights.setColorAt(i,new THREE.Color(item.kind==='bean'?0xe5b17b:0xfff9da)));
  const sparkGeometry=shade(new THREE.BoxGeometry(.08,.08,.08));
  const sparkMaterial=new THREE.MeshBasicMaterial({color:0xffd68a,vertexColors:true});
  const sparks=new THREE.InstancedMesh(sparkGeometry,sparkMaterial,24);
  sparks.frustumCulled=false;root.add(sparks);
  const transform=new THREE.Object3D(),burst=[];
  function collect(id,time) {
    const item=all.find(i=>i.id===id);if(!item)return;
    burst.push({time,x:Math.sin(item.angle)*RADIUS,y:item.y,z:Math.cos(item.angle)*RADIUS});
    if(burst.length>3)burst.shift();
  }
  function update(run,time) {
    const states=new Map(run.ingredients.map(item=>[item.id,item]));
    all.forEach((item,haloIndex)=>{
      const taken=states.get(item.id)?.collected;
      const y=item.y+Math.sin(time*3.3+item.phase)*.065;
      transform.position.set(Math.sin(item.angle)*RADIUS,y,Math.cos(item.angle)*RADIUS);
      transform.rotation.set(0,item.angle+Math.sin(time*1.4+item.phase)*.3,item.kind==='bean'?.35:0);
      if(item.kind==='bean')transform.scale.set(.25,.36,.18);else transform.scale.setScalar(1);
      if(taken)transform.scale.setScalar(0);
      transform.updateMatrix();item.batch.setMatrixAt(item.index,transform.matrix);
      if(item.kind==='bean'&&seams) {
        transform.scale.setScalar(taken?0:1);transform.updateMatrix();seams.setMatrixAt(item.index,transform.matrix);
      }
      // A small cream highlight sits on the dimensional front of every icon.
      const radial=.17;
      transform.position.set(Math.sin(item.angle)*(RADIUS+radial)-Math.cos(item.angle)*.055,y+.12,
        Math.cos(item.angle)*(RADIUS+radial)+Math.sin(item.angle)*.055);
      transform.scale.set(taken?0:.045,taken?0:.082,taken?0:.022);transform.rotation.set(0,item.angle,0);
      transform.updateMatrix();highlights.setMatrixAt(haloIndex,transform.matrix);
      transform.position.set(Math.sin(item.angle)*RADIUS,y,Math.cos(item.angle)*RADIUS);
      if(assets.camera)transform.quaternion.copy(assets.camera.quaternion);
      else transform.rotation.set(0,item.angle,0);
      transform.scale.setScalar(taken?0:1+Math.sin(time*3+item.phase)*.06);transform.updateMatrix();
      halos.setMatrixAt(haloIndex,transform.matrix);
      const platform=run.platforms[item.platform];
      transform.position.y=platform.y+.024;transform.rotation.set(0,0,0);
      transform.scale.setScalar(taken||platform.collapsed?0:1);transform.updateMatrix();
      shadows.setMatrixAt(haloIndex,transform.matrix);
    });
    for(const batch of Object.values(batches))batch.instanceMatrix.needsUpdate=true;
    if(seams)seams.instanceMatrix.needsUpdate=true;
    halos.instanceMatrix.needsUpdate=true;
    highlights.instanceMatrix.needsUpdate=true;shadows.instanceMatrix.needsUpdate=true;
    const last=burst[burst.length-1],age=last?time-last.time:10;
    for(let i=0;i<24;i++) {
      if(age<.6) {
        const a=i*2.39996,speed=.55+(i%5)*.18;
        transform.position.set(last.x+Math.cos(a)*age*speed,last.y+.2+age*(1.8+i%3*.25)-age*age*2.5,last.z+Math.sin(a)*age*speed);
        transform.scale.setScalar((1-age/.6)*(.65+i%3*.22));transform.rotation.set(age*4,a,age*3);
      } else transform.scale.setScalar(0);
      transform.updateMatrix();sparks.setMatrixAt(i,transform.matrix);
    }
    sparks.instanceMatrix.needsUpdate=true;
  }
  return {root,update,collect,dispose(){
    world.remove(root);
    for(const b of [...Object.values(batches),halos,seams,sparks,highlights,shadows])b?.dispose();
    for(const geometry of [sphere,drop,star,seam,haloGeometry,shadowGeometry,sparkGeometry])geometry.dispose();
    material.dispose();haloMaterial.dispose();sparkMaterial.dispose();shadowMaterial.dispose();glowTexture.dispose();
  }};
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

// All surfaces and furniture are original, deliberately small café geometry.
// Gameplay colliders remain in rules.js; every landing surface uses those angles.
const TAU = Math.PI * 2;
const WHITE = 0xffffff;
const C = {
  cream: 0xf2f0e8, green: 0x006241, forest: 0x1e3932,
  gold: 0xc8a66a, brown: 0x6f4e37, amber: 0xffcf7b
};
const TILE = {
  ceramic: 0, wood: 1, biscuit: 2, brick: 3, green: 4, gold: 5,
  awning: 6, edge: 7, coffee: 8, foam: 9, leaf: 10, crack: 11,
  inset: 12, pot: 13, lantern: 14, white: 15
};
const identity = new THREE.Matrix4();
const lightDirection = new THREE.Vector3(-0.35, 0.88, 0.32).normalize();

function transform(x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = 1, sz = 1) {
  return new THREE.Matrix4().compose(
    new THREE.Vector3(x, y, z),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)),
    new THREE.Vector3(sx, sy, sz)
  );
}

function tintGeometry(geometry, tile, color = WHITE, shade = true) {
  const uv = geometry.getAttribute('uv');
  const position = geometry.getAttribute('position');
  const normals = geometry.getAttribute('normal');
  const outUV = new Float32Array(position.count * 2);
  const colors = new Float32Array(position.count * 3);
  const base = new THREE.Color(color);
  const normal = new THREE.Vector3();
  for (let i = 0; i < position.count; i++) {
    let u = uv ? uv.getX(i) : 0.5;
    let v = uv ? uv.getY(i) : 0.5;
    u = Math.max(0.018, Math.min(0.982, u));
    v = Math.max(0.018, Math.min(0.982, v));
    outUV[i * 2] = ((tile % 4) + u) / 4;
    outUV[i * 2 + 1] = (3 - Math.floor(tile / 4) + v) / 4;
    let amount = 1;
    if (shade && normals) {
      normal.fromBufferAttribute(normals, i);
      amount = 0.59 + Math.max(0, normal.dot(lightDirection)) * 0.41;
    }
    colors[i * 3] = base.r * amount;
    colors[i * 3 + 1] = base.g * amount;
    colors[i * 3 + 2] = base.b * amount;
  }
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(outUV, 2));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  return geometry;
}

function prepared(geometry, matrix, tile, color = WHITE, shade = true) {
  geometry.applyMatrix4(matrix || identity);
  return tintGeometry(geometry, tile, color, shade);
}

function combine(parts) {
  if (!parts.length) return new THREE.BufferGeometry();
  const ready = parts.map(part => {
    const geometry = part.index ? part.toNonIndexed() : part;
    if (geometry !== part) part.dispose();
    const count = geometry.getAttribute('position').count;
    if (!geometry.getAttribute('normal')) geometry.computeVertexNormals();
    if (!geometry.getAttribute('uv')) geometry.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(count * 2), 2));
    if (!geometry.getAttribute('color')) {
      const values = new Float32Array(count * 3); values.fill(1);
      geometry.setAttribute('color', new THREE.Float32BufferAttribute(values, 3));
    }
    return geometry;
  });
  const geometry = mergeGeometries(ready, false);
  ready.forEach(part => part.dispose());
  if (!geometry) throw new Error('Café geometry could not be merged');
  return geometry;
}

function addBox(parts, x, y, z, w, h, d, tile, color = WHITE, ry = 0) {
  parts.push(prepared(new THREE.BoxGeometry(w, h, d), transform(x, y, z, 0, ry), tile, color));
}

function addSphere(parts, x, y, z, sx, sy, sz, tile, color = WHITE) {
  parts.push(prepared(new THREE.SphereGeometry(1, 8, 5), transform(x, y, z, 0, 0, 0, sx, sy, sz), tile, color));
}

function addCylinder(parts, x, y, z, top, bottom, height, tile, color = WHITE, segments = 10) {
  parts.push(prepared(new THREE.CylinderGeometry(top, bottom, height, segments), transform(x, y, z), tile, color));
}

function addTube(parts, from, to, radius, tile, color = WHITE, segments = 6) {
  const a = new THREE.Vector3(...from), b = new THREE.Vector3(...to);
  const position = a.clone().add(b).multiplyScalar(0.5);
  const rotation = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.clone().sub(a).normalize());
  const matrix = new THREE.Matrix4().compose(position, rotation, new THREE.Vector3(1, 1, 1));
  parts.push(prepared(new THREE.CylinderGeometry(radius, radius, a.distanceTo(b), segments), matrix, tile, color));
}

function addRing(parts, y, radius, thickness, tile, color = WHITE, segments = 48) {
  const geometry = new THREE.TorusGeometry(radius, thickness, 5, segments);
  parts.push(prepared(geometry, transform(0, y, 0, Math.PI / 2), tile, color));
}

function sectorGeometry(halfWidth, inner, outer, top, bottom, count = 24) {
  const positions = [], uv = [];
  function point(radius, angle, y) {
    return [Math.sin(angle) * radius, y, Math.cos(angle) * radius];
  }
  function face(a, b, c, uva, uvb, uvc) {
    positions.push(...a, ...b, ...c);
    uv.push(...uva, ...uvb, ...uvc);
  }
  for (let i = 0; i < count; i++) {
    const u = i / count, v = (i + 1) / count;
    const a = -halfWidth + u * halfWidth * 2, b = -halfWidth + v * halfWidth * 2;
    face(point(inner, a, top), point(outer, a, top), point(outer, b, top), [u, 0], [u, 1], [v, 1]);
    face(point(inner, a, top), point(outer, b, top), point(inner, b, top), [u, 0], [v, 1], [v, 0]);
    if (bottom === top) continue;
    for (const radius of [inner, outer]) {
      face(point(radius, a, bottom), point(radius, b, top), point(radius, a, top), [u, 0], [v, 1], [u, 1]);
      face(point(radius, a, bottom), point(radius, b, bottom), point(radius, b, top), [u, 0], [v, 0], [v, 1]);
    }
    face(point(inner, a, bottom), point(outer, b, bottom), point(outer, a, bottom), [u, 0], [v, 1], [u, 1]);
    face(point(inner, a, bottom), point(inner, b, bottom), point(outer, b, bottom), [u, 0], [v, 0], [v, 1]);
  }
  if (top !== bottom) {
    for (const angle of [-halfWidth, halfWidth]) {
      face(point(inner, angle, top), point(outer, angle, top), point(outer, angle, bottom), [0, 1], [1, 1], [1, 0]);
      face(point(inner, angle, top), point(outer, angle, bottom), point(inner, angle, bottom), [0, 1], [1, 0], [0, 0]);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.computeVertexNormals();
  return geometry;
}

function bevelledLedge(halfWidth, inner, outer, thickness) {
  const positions=[],uv=[],steps=24,bevel=Math.min(.065,thickness*.25);
  const levels=[{y:0,i:inner+bevel,o:outer-bevel,a:halfWidth-.007},
    {y:-bevel,i:inner,o:outer,a:halfWidth},
    {y:-thickness+bevel,i:inner,o:outer,a:halfWidth},
    {y:-thickness,i:inner+bevel,o:outer-bevel,a:halfWidth-.007}];
  const point=(level,outerSide,t)=>{
    const a=(t*2-1)*level.a,r=outerSide?level.o:level.i;
    return [Math.sin(a)*r,level.y,Math.cos(a)*r];
  };
  function triangle(a,b,c,ua,ub,uc){positions.push(...a,...b,...c);uv.push(...ua,...ub,...uc);}
  function quad(a,b,c,d,u=0,v=1){
