export function formatTime(seconds = 0) {
  const finite = Math.max(0, Number(seconds) || 0);
  const minutes = Math.floor(finite / 60), rest = (finite % 60).toFixed(2).padStart(5, '0');
  return `${minutes}:${rest}`;
}
